    <script>
      function el(tag, attrs, ...children) {
        const node = document.createElement(tag);
        const properties = attrs || {};

        for (const [key, value] of Object.entries(properties)) {
          if (value == null || value === false) {
            continue;
          }

          if (key === "className") {
            node.className = value;
          } else if (key === "textContent") {
            node.textContent = value;
          } else if (key in node && key !== "role") {
            node[key] = value;
          } else {
            node.setAttribute(key, value);
          }
        }

        const append = (child) => {
          if (child == null || child === false) return;
          if (Array.isArray(child)) {
            child.forEach(append);
          } else if (child instanceof Node) {
            node.appendChild(child);
          } else {
            node.appendChild(document.createTextNode(String(child)));
          }
        };

        children.forEach(append);
        return node;
      }

      function FormField({ id, label, required, helperText, type = "text", placeholder, autoComplete }) {
        const errorId = `${id}-error`;
        const helpId = `${id}-help`;
        const input = el("input", {
          id,
          name: id,
          type,
          placeholder,
          autoComplete,
          "aria-invalid": "false",
          "aria-describedby": helperText ? `${helpId} ${errorId}` : errorId,
        });
        const error = el("div", { id: errorId, className: "error", role: "alert" });

        const field = el(
          "div",
          { className: "form-field" },
          el(
            "label",
            { htmlFor: id },
            label,
            required ? el("span", { className: "required" }, " *") : null
          ),
          input,
          helperText ? el("div", { id: helpId, className: "helper" }, helperText) : null,
          error
        );

        return { field, input, error };
      }

      function validate(values) {
        const nextErrors = {};
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        const phonePattern = /^[+()\-.\s\d]{7,}$/;

        if (!values.fullName.trim()) {
          nextErrors.fullName = "Full name is required.";
        }

        if (!values.email.trim()) {
          nextErrors.email = "Email address is required.";
        } else if (!emailPattern.test(values.email.trim())) {
          nextErrors.email = "Enter a valid email address.";
        }

        if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
          nextErrors.phone = "Enter a valid phone number, such as +1 555 123 4567.";
        }

        return nextErrors;
      }

      function ContactForm() {
        const state = {
          values: {
            fullName: "",
            email: "",
            phone: "",
          },
          touched: {
            fullName: false,
            email: false,
            phone: false,
          },
          submitted: false,
        };

        const fullNameField = FormField({
          id: "fullName",
          label: "Full name",
          required: true,
          placeholder: "Jane Doe",
          autoComplete: "name",
        });
        const emailField = FormField({
          id: "email",
          label: "Email address",
          required: true,
          type: "email",
          placeholder: "jane@example.com",
          autoComplete: "email",
        });
        const phoneField = FormField({
          id: "phone",
          label: "Phone number",
          required: false,
          placeholder: "+1 555 123 4567",
          autoComplete: "tel",
          helperText: "Optional. Use a format like +1 555 123 4567 or 555-123-4567.",
        });
        const success = el("div", {
          className: "success",
          role: "status",
          "data-visible": "false",
          textContent: "Thanks — your message has been submitted.",
        });

        function syncField(field, node) {
          const shouldShowError = state.touched[field] || state.submitted;
          node.error.textContent = shouldShowError && validation[field] ? validation[field] : "";
          node.input.setAttribute("aria-invalid", shouldShowError && validation[field] ? "true" : "false");
        }

        function syncAll() {
          const validation = validate(state.values);
          syncField("fullName", fullNameField, validation);
          syncField("email", emailField, validation);
          syncField("phone", phoneField, validation);
          success.setAttribute("data-visible", state.submitted && Object.keys(validation).length === 0 ? "true" : "false");
        }

        function updateValue(field, node) {
          return (event) => {
            state.values[field] = event.target.value;
            state.submitted = false;
            syncAll();
          };
        }

        function touchField(field) {
          return () => {
            state.touched[field] = true;
            syncAll();
          };
        }

        const form = el("form", { noValidate: true });
        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.touched = { fullName: true, email: true, phone: true };
          const validation = validate(state.values);
          state.submitted = Object.keys(validation).length === 0;
          syncAll();
        });

        fullNameField.input.addEventListener("input", updateValue("fullName"));
        fullNameField.input.addEventListener("blur", touchField("fullName"));
        emailField.input.addEventListener("input", updateValue("email"));
        emailField.input.addEventListener("blur", touchField("email"));
        phoneField.input.addEventListener("input", updateValue("phone"));
        phoneField.input.addEventListener("blur", touchField("phone"));

        form.append(fullNameField.field, emailField.field, phoneField.field, el("div", { className: "actions" }, el("button", { type: "submit" }, "Send message")), success);

        const card = el(
          "div",
          { className: "card" },
          el(
            "div",
            { className: "hero" },
            el("p", { className: "eyebrow" }, "Support"),
            el("h1", null, "Contact our team"),
            el("p", null, "Send us your details and we’ll get back to you as soon as possible.")
          ),
          el("div", { className: "form-wrap" }, form)
        );

        syncAll();
        return card;
      }

      function App() {
        return el("main", { className: "page" }, ContactForm());
      }

      document.getElementById("root").appendChild(App());
    </script>
